iption\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [683, 191, 934, 257], \"page_id\": 4}], \"content\": \"Contents\", \"description\": null, \"id\": 4, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1455, 97, 1490, 123], \"page_id\": 5}], \"content\": \"VII\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [304, 217, 1319, 288], \"page_id\": 5}], \"content\": \"Nonquarterly Tables and Reports\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [304, 314, 1328, 389], \"page_id\": 5}], \"content\": \"For the convenience of the \\\"Treasury Bulletin\\\" user, nonquarterly tables and reports are listed below along with the issues in which they appear.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [173, 429, 1475, 1864], \"page_id\": 5}], \"content\": \"<table><tr><th colspan=\\\"5\\\">Federal Fiscal Operations</th></tr><tr><th></th><th>March</th><th>June</th><th>Sept.</th><th>Dec.</th></tr><tr><td>FFO-5.\\u2014Internal Revenue Receipts by State</td><td></td><td></td><td></td><td>v</td></tr><tr><td>FFO-6.\\u2014Customs Collections of Duties, Taxes and Fees by Districts and Ports</td><td></td><td></td><td></td><td>v</td></tr><tr><th colspan=\\\"5\\\">Special Reports</th></tr><tr><td>Financial Report of the United States Government excerpt</td><td></td><td>v</td><td></td><td></td></tr><tr><th colspan=\\\"5\\\">Trust Fund Reports:</th></tr><tr><td>Airport and Airway Trust Fund</td><td>v</td><td></td><td></td><td></td></tr><tr><td>Aquatic Resources Trust Fund</td><td>v</td><td></td><td></td><td></td></tr><tr><td>Black Lung Disability Trust Fund</td><td>v</td><td></td><td></td><td></td></tr><tr><td>Civil Service Retirement and Disability Fund</td><td></td><td></td><td></td><td>v</td></tr><tr><td>Federal Disability Insurance Trust Fund</td><td></td><td></td><td></td><td>v</td></tr><tr><td>Federal Hospital Insurance Trust Fund</td><td></td><td>