 xi**2, xi, 1])\n\n# Transpose of X\nXT = list(zip(*X))\n\n# X^T * X (4x4 matrix)\nXTX = [[sum([XT[i][j]*X[j][i] for j in range(n)]) for i in range(4)] for j in range(4)]\n\n# X^T * y\nXTy = [sum([XT[i][j]*y_arr[j] for j in range(n)]) for i in range(4)]\n\n# Now solve the 4x4 system using Gaussian elimination\ndef gaussian_solve(A, b):\n    n = len(A)\n    # Augmented matrix\n    M = [A[i][:] + [b[i]] for i in range(n)]\n    \n    # Forward elimination\n    for i in range(n):\n        # Find pivot\n        max_row = i\n        for r in range(i+1, n):\n            if abs(M[r][i]) > abs(M[max_row][i]):\n                max_row = r\n        M[i], M[max_row] = M[max_row], M[i]\n        \n        # Make sure diagonal is non-zero\n        if abs(M[i][i]) < 1e-10:\n            continue\n            \n        # Eliminate\n        for r in range(i+1, n):\n            factor = M[r][i] / M[i][i]\n            for c in range(i, n+1):\n                M[r][c] -= factor * M[i][c]\n    \n    # Back substitution\n    x = [0]*n\n    for i in range(n-1, -1, -1):\n        if abs(M[i][i]) < 1e-10:\n            x[i] = 0\n        else:\n            x[i] = M[i][n] - sum([M[i][j]*x[j] for j in range(i+1, n)])\n            x[i] /= M[i][i]\n    \n    return x\n\ncoeffs = gaussian_solve(XTX, XTy)\n# coeffs = [a, b, c, d] for y = a*x^3 + b*x^2 + c*x + d\na, b, c, d = coeffs\n\nprint(f\"Cubic polynomial: y = {a:.6f}*x^3 + {b:.6f}*x^2 + {c:.6f}*x + {d:.6f}\")\nprint(f\"where x = (year - {offset}) / {scale}\")\n\n# Predict for year 2025\nx_2025 = (2025 - offset) / scale\ny_2025 = a*x_2025**3 + b*x_2025**2 + c*x_2025 + d\n\nprint(f\"\\nPredicted surplus/deficit for 2025: {y_2025:.2f} million dollars\")\n\n# Compute R-squared\ny_pred = [a*xi**3 + b*xi**2 + c*xi + d for xi in x]\ny_mean = sum(y_arr)/len(y_arr)\nss_res = sum([(y_arr[i] - y_pred[i])**2 for i in range(n)])\nss_tot = sum([(yi - y_mean)**2 for yi in y_arr])\nr_squared = 1 - ss_res/ss_tot\n\nprint(f\"R-squared: {r_squared:.6f}\")\n\n# Print predictions for each year to check fit\nprint(\"\\nYear-by-year predictions:\")\nfor i, yr in enumerate(years):\n    print(f\"{yr}: actual={y_arr[i]}, predicted={y_pred[i]:.0f}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
